"""Demo: strict ascent of the Boolean staircase, witnessed by indicators."""
from __future__ import annotations
from typing import Tuple


def in_rung(f: Tuple[int, ...], n: int) -> bool:
    """True iff f lies in rung I_n = {f : f(i)=0 for all i>=n}."""
    return all(v == 0 for i, v in enumerate(f) if i >= n)


def indicator(n: int, length: int) -> Tuple[int, ...]:
    """The indicator e_n: 1 at index n, 0 elsewhere."""
    return tuple(1 if i == n else 0 for i in range(length))


def main() -> None:
    length = 10
    for n in range(8):
        e = indicator(n, length)
        assert in_rung(e, n + 1) and not in_rung(e, n)
        print(f"e_{n} separates rung {n} from rung {n+1}: "
              f"in I_{n+1}={in_rung(e, n+1)}, in I_{n}={in_rung(e, n)}")
    print("Every step of the staircase is a proper inclusion.")


if __name__ == "__main__":
    main()

